Here is a clean Template Method implementation for sorting algorithms in Python:

```python
from abc import ABC, abstractmethod
from typing import List, Any

class SortAlgorithm(ABC):
    """Template Method skeleton"""
    def sort(self, data: List[Any]) -> List[Any]:
        # Template method - defines the skeleton
        arr = data[:]
        n = len(arr)
        self._sort(arr, n)
        return arr

    @abstractmethod
    def _sort(self, arr: List[Any], n: int) -> None:
        """Primitive operation - specific to each algorithm"""
        pass

    @abstractmethod
    def compare(self, a: Any, b: Any) -> bool:
        """Primitive operation - compare two elements"""
        pass

    @abstractmethod
    def swap(self, arr: List[Any], i: int, j: int) -> None:
        """Primitive operation - swap two elements"""
        pass


class BubbleSort(SortAlgorithm):
    def _sort(self, arr: List[Any], n: int) -> None:
        for i in range(n):
            for j in range(0, n - i - 1):
                if self.compare(arr[j], arr[j + 1]):
                    self.swap(arr, j, j + 1)

    def compare(self, a: Any, b: Any) -> bool:
        return a > b

    def swap(self, arr: List[Any], i: int, j: int) -> None:
        arr[i], arr[j] = arr[j], arr[i]


class SelectionSort(SortAlgorithm):
    def _sort(self, arr: List[Any], n: int) -> None:
        for i in range(n):
            min_idx = i
            for j in range(i + 1, n):
                if self.compare(arr[min_idx], arr[j]):
                    min_idx = j
            if min_idx != i:
                self.swap(arr, i, min_idx)

    def compare(self, a: Any, b: Any) -> bool:
        return a > b

    def swap(self, arr: List[Any], i: int, j: int) -> None:
        arr[i], arr[j] = arr[j], arr[i]


# Test
if __name__ == "__main__":
    ints = [64, 25, 12, 22, 11]
    strs = ["banana", "apple", "cherry", "date"]

    for algo_cls in [BubbleSort, SelectionSort]:
        algo = algo_cls()
        print(algo_cls.__name__, "ints:", algo.sort(ints))
        print(algo_cls.__name__, "strs:", algo.sort(strs))
```

The `SortAlgorithm.sort` is the template method. Concrete subclasses provide the algorithm-specific `_sort` implementation and the primitive operations `compare` and `swap`.
